-- Fix a stale interest rate and seed detailed per-loan-type reference data
-- sourced from a direct read of the current loan regulations on
-- nktscoop.com (ว่าด้วยเงินกู้สามัญและเงินกู้เพื่อเหตุฉุกเฉิน พ.ศ. 2569,
-- effective 1 ก.พ. 2569; เงินกู้สามัญพิเศษดอกเบี้ยต่ำ พ.ศ. 2567; เงินกู้พิเศษ
-- เพื่อการโอนหนี้ พ.ศ. 2567; เงินกู้สามัญพิเศษช่วยเหลือผู้ค้ำ/ทายาท พ.ศ. 2568).
-- Kept in sync with DEFAULT_KNOWLEDGE in lib/knowledge.ts.
--
-- loan_rates previously said the low-interest special loan was "4.50%"
-- (an annual figure that doesn't match "0.75% ต่อเดือน" in the regulation —
-- 0.75%/month compounds to roughly 9%/year, not 4.5%) — corrected here.
UPDATE "KnowledgeEntry"
SET "content" = 'ทั่วไป (เงินกู้สามัญ, เพื่อการดำรงชีพ, ฉุกเฉิน, เพื่อการโอนหนี้, ปรับโครงสร้างหนี้) 5.25% ต่อปี | โครงการพิเศษดอกเบี้ยต่ำ (วงเงินไม่เกิน 500,000 บาท ผ่อน 72 งวด) 0.75% ต่อเดือน (อัตรา ณ ปัจจุบันตามประกาศคณะกรรมการ อาจเปลี่ยนแปลงได้ ควรยืนยันกับเจ้าหน้าที่หากไม่แน่ใจ)',
    "title" = 'อัตราดอกเบี้ยเงินกู้',
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "key" = 'loan_rates';

INSERT INTO "KnowledgeEntry" ("id", "key", "title", "content", "sortOrder", "updatedAt") VALUES
  ('know_loan_normal_limits', 'loan_normal_limits', 'วงเงินกู้สามัญ (ระเบียบ พ.ศ. 2569 บังคับใช้ 1 ก.พ. 2569)', 'วงเงินสูงสุด 100 เท่าของเงินเดือน ต้องมีหุ้นไม่น้อยกว่า 20% ของวงเงินกู้ | อายุตัวไม่เกิน 55 ปี กู้ได้ไม่เกิน 2,000,000 บาท ผ่อนได้ 150 งวด | อายุ 56 ปี ไม่เกิน 2,000,000 บาท (ส่วนเกินหนี้เดิมกู้เพิ่มได้ไม่เกิน 1,000,000 บาท) | เพดานสูงสุดรวม 3,000,000 บาท ขึ้นกับอายุสมาชิก | จำนวนผู้ค้ำประกันตามวงเงิน: ไม่เกิน 300,000 บาท ใช้ผู้ค้ำ 1 คน, เกิน 300,000-800,000 บาท 2 คน, เกิน 800,000-900,000 บาท 3 คน, เกิน 900,000-1,150,000 บาท 4 คน, เกิน 1,150,000-2,000,000 บาท 5 คน, เกิน 2,000,000-3,000,000 บาท 6 คน | วงเงินไม่เกิน 90% ของหุ้นไม่ต้องมีผู้ค้ำ | ยื่นคำขอภายในวันที่ 5 ของทุกเดือน (ตัวเลขอนุมัติจริงต้องให้เจ้าหน้าที่ตรวจสอบเสมอ)', 7, CURRENT_TIMESTAMP),
  ('know_loan_subsistence', 'loan_subsistence', 'เงินกู้เพื่อการดำรงชีพ (ATM)', 'วงเงินไม่เกินครึ่งหนึ่งของเงินได้รายเดือน เพดานตามอายุตัว: ไม่เกิน 55 ปี 2,000,000 บาท / ไม่เกิน 56 ปี 1,500,000 บาท / 57 ปีขึ้นไป 1,000,000 บาท | ผ่อนได้สูงสุด 150 งวด | ไม่ต้องมีผู้ค้ำประกัน | เอกสาร: สลิปเงินเดือนย้อนหลัง 3 เดือน รับรองสำเนาโดยผู้บังคับบัญชา | ยื่นคำขอได้ทุกวันทำการก่อนเวลา 12.00 น. เอกสารครบอนุมัติและถอนได้วันถัดไป', 8, CURRENT_TIMESTAMP),
  ('know_loan_emergency', 'loan_emergency', 'เงินกู้เพื่อเหตุฉุกเฉิน', 'กรณีปกติ: กู้ได้ไม่เกิน 15 เท่าของเงินเดือนส่วนที่เหลือหลังหักชำระหนี้ หรือไม่เกิน 90% ของหุ้น (เลือกวิธีที่ให้วงเงินมากกว่า) ผ่อนไม่เกิน 12 งวด ไม่ต้องมีผู้ค้ำประกัน | กรณีพิเศษ (สมัคร สสอค./สส.ชสอ./สส.สท./สส.สก./สส.อร./ประกันชีวิตสหกรณ์): ไม่เกินวงเงินค่าสมัคร ผ่อนไม่เกิน 12 งวด กู้พร้อมกรณีปกติในคราวเดียวกันได้ | ยื่นคำขอพร้อมเอกสารครบก่อนเวลา 12.00 น. ทุกวันทำการ รับเงินสดหรือโอนได้วันเดียวกัน', 9, CURRENT_TIMESTAMP),
  ('know_loan_low_interest_special', 'loan_low_interest_special', 'เงินกู้สามัญพิเศษดอกเบี้ยต่ำ', 'วงเงินกู้สูงสุด 500,000 บาท ดอกเบี้ย 0.75% ต่อเดือน ผ่อนชำระเงินต้น+ดอกเบี้ยเท่ากันทุกงวด 72 งวด | คุณสมบัติ: เป็นสมาชิกและทำงานมาแล้วไม่น้อยกว่า 3 เดือน ไม่เคยผิดนัดชำระหนี้กับสหกรณ์ | ผู้ค้ำประกัน: วงเงินไม่เกิน 200,000 บาท ใช้ผู้ค้ำ 1 คน / วงเงิน 200,000-500,000 บาท ใช้ผู้ค้ำ 2 คน | ผิดนัดชำระเกิน 3 งวด ปรับเป็นหนี้ผิดนัดทันที (ระเบียบบังคับใช้ตั้งแต่ 4 ธ.ค. 2567)', 10, CURRENT_TIMESTAMP),
  ('know_loan_debt_transfer', 'loan_debt_transfer', 'เงินกู้พิเศษเพื่อการโอนหนี้จากสถาบันการเงินอื่น', 'สำหรับสมาชิกที่มีหนี้กับธนาคาร/สถาบันการเงินอื่นที่ดอกเบี้ยสูงกว่าสหกรณ์ ให้กู้เพื่อนำไปปิดหนี้เดิม โอนภาระมาอยู่กับสหกรณ์แทน | เอกสารเพิ่มเติมเฉพาะประเภทนี้: รายการเคลื่อนไหวบัญชี (Statement) หรือหนังสือรับรองยอดหนี้จากสถาบันการเงินเดิม และเอกสารเครดิตบูโร (NCB)', 11, CURRENT_TIMESTAMP),
  ('know_loan_guarantor_heir_special', 'loan_guarantor_heir_special', 'เงินกู้สามัญพิเศษ ช่วยเหลือผู้ค้ำประกัน/ทายาท/ผู้รับสภาพหนี้', 'สำหรับสมาชิกที่ต้องรับภาระหนี้แทนผู้กู้เดิมในฐานะผู้ค้ำประกัน/ทายาท/ผู้รับสภาพหนี้ (กรณีผู้กู้เดิมเสียชีวิต ถูกฟ้อง หรือผิดนัดชำระ) ให้กู้เงินก้อนใหม่มาผ่อนแทนหนี้ที่รับภาระมา แทนการแบกดอกเบี้ยผิดนัดอัตราสูง | แบบฟอร์มคำขอดาวน์โหลดได้ที่หน้าดาวน์โหลดเอกสารของเว็บไซต์สหกรณ์ | เป็นกรณีละเอียดอ่อนเกี่ยวข้องกับการเสียชีวิต/คดีความของผู้อื่นเสมอ ให้แนะนำติดต่อเจ้าหน้าที่สินเชื่อตรวจสอบเป็นรายกรณี ห้ามตอบเองว่าเข้าเกณฑ์หรือไม่', 12, CURRENT_TIMESTAMP),
  ('know_loan_documents_checklist', 'loan_documents_checklist', 'เอกสารประกอบคำขอกู้สามัญ / ดำรงชีพ / ฉุกเฉิน', 'ผู้กู้และคู่สมรส: สำเนาบัตรประชาชน, สำเนาทะเบียนบ้าน, ทะเบียนสมรส (กรณีหย่า/หม้ายแนบเอกสารเพิ่ม), สลิปเงินเดือนย้อนหลัง 3 เดือนรับรองสำเนาโดยผู้บังคับบัญชา, แบบสอบถามหนี้ธนาคารออมสิน | ผู้ค้ำประกัน: สำเนาบัตรประชาชน, สำเนาทะเบียนบ้าน (ไม่ต้องมีเอกสารคู่สมรสผู้ค้ำ) | เงินกู้ฉุกเฉินไม่ต้องมีผู้ค้ำประกัน ใช้เอกสารผู้กู้ชุดเดียวกัน | ใช้ปากกาสีน้ำเงินเท่านั้นในการลงนามเอกสารทุกฉบับ', 13, CURRENT_TIMESTAMP)
ON CONFLICT ("key") DO NOTHING;
